// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { largeGraphTooltip, tooltipPlacement } from "../../../main/frontend/graph-explorer/large-graph-tooltip.ts";

test("the large-graph tooltip shows the label and the full IRI", () => {
  assert.deepEqual(largeGraphTooltip({ id: "http://example.org/alice", label: "Alice", kind: "iri" }), {
    title: "Alice",
    detail: "http://example.org/alice",
  });
  assert.deepEqual(largeGraphTooltip({ id: "__rdf_bnode__:b1", label: "b1", kind: "blank" }), {
    title: "b1",
    detail: "_:b1",
  });
  assert.deepEqual(largeGraphTooltip({ id: '__rdf_literal__:x', label: "Hello", kind: "literal" }), {
    title: "Hello",
    detail: "",
  });
});

test("the tooltip sits beside the pointer and flips back inside the stage near its right and bottom edges", () => {
  const stage = { left: 10, top: 20, width: 500, height: 300 };
  assert.deepEqual(tooltipPlacement({ x: 110, y: 120 }, stage, { width: 100, height: 40 }), { left: 112, top: 114 });
  const flipped = tooltipPlacement({ x: 500, y: 310 }, stage, { width: 100, height: 40 });
  assert.ok(flipped.left + 100 <= 500 && flipped.top + 40 <= 300);
  assert.ok(flipped.left >= 0 && flipped.top >= 0);
});
